import struct
# simulate 32-bit int overflow
def parse_number(digits):
    number = 0
    for d in digits:
        number = (number * 10 + int(d)) & 0xFFFFFFFF
        if number >= 0x80000000:
            number -= 0x100000000
    return number

# find a digit string that overflows to a large positive value
# try long strings of 9s
for n in range(1, 30):
    digits = '9'*n
    val = parse_number(digits)
    if val > 100000:
        print(f'{n} nines -> {val}')
        break
